ALTER FUNCTION public.financial_report_snapshot(date,date) RENAME TO financial_report_snapshot_legacy;
CREATE FUNCTION public.financial_report_snapshot(_start date,_end date) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE result jsonb; opening_due numeric; billed numeric; closing_due numeric; fy integer; fydate date; opening numeric; today date:=(now() AT TIME ZONE 'Asia/Kolkata')::date; BEGIN
result:=public.financial_report_snapshot_legacy(_start,_end);
WITH calc AS (SELECT public.billed_total(f.id,f.billing_start,_start) before_bill,public.billed_total(f.id,greatest(date_trunc('month',billing_start)::date,_start),_end) period_bill,coalesce((SELECT sum(amount) FROM public.payments WHERE flat_id=f.id AND status='confirmed' AND paid_on<_start),0) before_paid,coalesce((SELECT sum(amount) FROM public.payments WHERE flat_id=f.id AND status='confirmed' AND paid_on<_end AND paid_on<=today),0) end_paid FROM public.flats f)
SELECT coalesce(sum(greatest(before_bill-before_paid,0)),0),coalesce(sum(period_bill),0),coalesce(sum(greatest(before_bill+period_bill-end_paid,0)),0) INTO opening_due,billed,closing_due FROM calc;
fy:=extract(year from _start)::int-CASE WHEN extract(month from _start)<(public.maintenance_rate(_start)).fy_start_month THEN 1 ELSE 0 END; fydate:=make_date(fy,(public.maintenance_rate(_start)).fy_start_month,1);
SELECT coalesce((SELECT opening_balance FROM public.fund_years WHERE fy_start=fy),0)+coalesce((SELECT sum(amount) FROM public.payments WHERE status='confirmed' AND paid_on>=fydate AND paid_on<_start),0)-coalesce((SELECT sum(amount) FROM public.expenses WHERE coalesce(expense_month,to_char(expense_date,'YYYY-MM'))>=to_char(fydate,'YYYY-MM') AND coalesce(expense_month,to_char(expense_date,'YYYY-MM'))<to_char(_start,'YYYY-MM')),0) INTO opening;
RETURN result||jsonb_build_object('openingOutstanding',opening_due,'maintenanceBilled',billed,'outstandingDues',closing_due,'openingBalance',opening,'closingBalance',opening+(result->>'totalIncome')::numeric-(result->>'totalExpenses')::numeric,'openingBalanceRecorded',EXISTS(SELECT 1 FROM public.fund_years WHERE fy_start=fy),'basis','Confirmed payment dates and recorded expense months. Maintenance uses immutable monthly charges and approved effective-month rates. Financial years follow approved configuration. Current periods are as of generation. No separate other-receipts records exist.'); END $$;
REVOKE ALL ON FUNCTION public.financial_report_snapshot_legacy(date,date) FROM PUBLIC,anon,authenticated; COMMENT ON FUNCTION public.financial_report_snapshot_legacy(date,date) IS 'DEPRECATED: internal transaction projection only; maintenance totals are replaced by financial_report_snapshot.';
REVOKE ALL ON FUNCTION public.financial_report_snapshot(date,date) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.financial_report_snapshot(date,date) TO authenticated;
CREATE OR REPLACE FUNCTION public.prepare_financial_report(_type text,_start date) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE finish date; rid uuid; payload jsonb; BEGIN
IF NOT public.has_role(auth.uid(),'treasurer') OR public.has_role(auth.uid(),'resident') AND NOT public.has_permission('finance.read') THEN RAISE EXCEPTION 'Treasurer access required' USING ERRCODE='42501'; END IF;
IF _type='monthly' THEN finish:=(_start+interval '1 month')::date; ELSIF _type='yearly' AND extract(month from _start)=(public.maintenance_rate(_start)).fy_start_month THEN finish:=(_start+interval '1 year')::date; ELSE RAISE EXCEPTION 'Invalid report period'; END IF;
IF _type='yearly' THEN finish:=least(finish,(date_trunc('month',now() AT TIME ZONE 'Asia/Kolkata')+interval '1 month')::date); END IF;
payload:=public.financial_report_snapshot(_start,finish); INSERT INTO public.financial_reports(period_type,period_start,period_end,prepared_by,prepared_email,snapshot) VALUES(_type,_start,finish,auth.uid(),coalesce(auth.jwt()->>'email',auth.uid()::text),payload) RETURNING id INTO rid; RETURN rid; END $$;